\label{thm:start3}
Let $g \in L^2({{\mathbb R}^d},{\mathbb R})$ be a real-valued window function, and let $\mathcal{L} \subseteq {{\mathbb R}^{2d}}$ be a separable lattice. Then there exist functions $f_1,f_2 \in {L^2({\mathbb R}^d)}$ which satisfy all of the following three properties:
\begin{enumerate}
    \item $|V_g(f_1)(z)|=|V_g(f_2)(z)|$ for all $z \in \mathcal{L}$
    \item $|f_1(t)| = |f_2(t)|$ for all $t \in {{\mathbb R}^d}$
    \item $f_1 \nsim f_2$.
\end{enumerate}

\label{thm:intro:sign_retrieval}
Let $g \in L^2({{\mathbb R}^d},{\mathbb R})$ be a real-valued window function, and suppose that $\mathcal{L} \subseteq {\mathbb R}^{2d}$ satisfies one of the following two conditions:
\begin{enumerate}
    \item $\mathcal{L} = \Lambda \times {\mathbb R}^d$ with $\Lambda$ a lattice in ${{\mathbb R}^d}$.
    \item $\mathcal{L}$ is a separable lattice.
\end{enumerate}
Then there exist two real-valued functions $f_1,f_2 \in L^2({{\mathbb R}^d},{\mathbb R})$ such that
$$
|V_g(f_1)(z)| = |V_g(f_2)(z)| \ \forall z \in \mathcal{L} \ \ \text{and} \ \ f_1 \nsim f_2.
$$

\label{lma:symplecticCharacterization}
Let $S \in \mathrm{GL}_{2d}({\mathbb R})$ be an invertible matrix such that
$$
S = \begin{pmatrix} A & B \\ C & D \end{pmatrix}
$$
with $A,B,C,D$ denoting block matrices in ${\mathbb R}^{d \times d}$. Then $S$ is symplectic if and only if $AC^T = A^TC$, $BD^T=B^TD$ and $A^TD - C^TB = I_d$.

\label{lma:block_diag_representation}
For $A \in \mathrm{GL}_d({\mathbb R})$ define the block-diagonal matrix $S_A$ via
$$
S_A = \begin{pmatrix}
A & 0 \\
0 & A^{-T}
\end{pmatrix}
$$
where $A^{-T} = (A^T)^{-1}$. Then the metaplectic operator $\mu(S_A)$ corresponding to $S_A$ is given by
$$
(\mu(S_A)f)(x) = |\det A |^{-1/2} f(A^{-1}x), \ \ f \in {L^2({\mathbb R}^d)}.
$$

\textbf{Proof of (1).}
Suppose that $\{ c_\lambda \} \in c_{00}(\mathcal{B}^*)$ is the defining sequence of $f \in \mathcal{V}_{\mathcal{B}^*}^S(\mathcal{R}g)$. Since $(\mathcal{B}^*)^* = \mathcal{B}$, Theorem \ref{thm:equalSpectrograms}(1) and the choice of $f$ implies that
\begin{equation}\label{eq:s1}
    |V_gf(z)| = |V_g(f_\times)(z)| \ \ \forall z \in S({{\mathbb R}^d} \times \mathcal{B}).
\end{equation}
The statement is therefore a consequence of the inclusion
\begin{equation}\label{eq:inclusion}
    \mathcal{L}=ST{\mathbb Z}^{2d} = S(A{\mathbb Z}^d \times B{\mathbb Z}^d) \subseteq S({\mathbb R}^d \times B{\mathbb Z}^d) = S({{\mathbb R}^d} \times \mathcal{B}).
\end{equation}
In view of identity \eqref{eq:s1}, the spectrogram of $f$ agrees with the spectrogram of $f_\times$ on the lattice $\mathcal{L}$.

\textbf{Proof of (2).}
To prove the second statement we observe that the condition $\mathfrak{p}_\mathcal{B}(\mu(S)^{-1}\mathcal{R}g) \in L^\infty(\mathcal{P}(\mathcal{B}))$ implies that $f = \sum_{\lambda \in \mathcal{B}^*} c_\lambda T_\lambda^S \mathcal{R}g$ converges unconditionally provided that $\{ c_\lambda \} \in \ell^2(\mathcal{B}^*)$. In a similar fashion to the proof of statement (1) we conclude from Theorem \ref{thm:equalSpectrograms}(2) that
$$
|V_gf(z)| = |V_g(f_\times)(z)| \ \ \forall z \in S({{\mathbb R}^d} \times \mathcal{B}),
$$
thereby proving the statement by invoking the inclusion given in \eqref{eq:inclusion}.

\textbf{Proof of (1).}
We start by proving the claim made in item (1). To that end, let $\mathcal{X} \subset {{\mathbb R}^d}$ be a finite set, $|\mathcal{X}|<\infty$, and let $c_x \in {\mathbb C}$ with $x \in \mathcal{X}$. Suppose that
\begin{equation}\label{eq:lin_indep_zero}
    \sum_{x \in \mathcal{X}} c_x T_x \phi = 0.
\end{equation}
We have to show that $c_x = 0$ for every $x \in \mathcal{X}$. To do so, we take the Fourier transform on both sides of equation \eqref{eq:lin_indep_zero} and obtain the relation
$$
 \underbrace{\sum_{x \in \mathcal{X}} c_x e^{-2\pi i x \cdot t}}_{\coloneqq E(t)} {\mathcal{F}} \phi(t) = 0.
$$
which holds for every $t \in {\mathbb R}$. Since $\phi\neq 0$ there exists a set $\mathcal{Y} \subseteq {{\mathbb R}^d}$ of positive $d$-dimensional Lebesgue measure such that ${\mathcal{F}} \phi (t) \neq 0$ for almost every $t \in \mathcal{Y}$. Hence, the map $E$ must vanish almost everywhere on $\mathcal{Y}$. But $E$ extends from ${{\mathbb R}^d}$ to a holomorphic function of $d$ complex variables. Therefore, Lemma \ref{lma:elementary_uniqueness} shows that $E$ must vanish identically. Now observe that since $\mathcal{X}$ is a set, all its elements are distinct. A general theorem on the linear independence of characters due to Artin \cite[Theorem 4.1]{lang2005algebra} shows that the complex exponentials $t \mapsto e^{-2\pi i t \cdot x}, x \in \mathcal{X}$, are linearly independent. Hence, the property that $E$ vanishes identically implies that $c_x=0$ for all $x \in \mathcal{X}$ and this concludes the proof of the claim.

\textbf{Proof of (2).}
We continue with the proof of the second statement. First, observe that since $\mathfrak{p}_{\Lambda^*}[\phi] \in L^\infty(\mathcal{P}(\Lambda^*))$ it follows from Proposition \ref{prop:bessel_condition} that the series $\sum_{\lambda \in \Lambda} c_\lambda T_\lambda \phi$ converges unconditionally for every $\{ c_\lambda \} \in \ell^2(\Lambda)$. Now suppose that $\{ c_\lambda \} \in \ell^2(\Lambda)$ is such that $\sum_{\lambda \in \Lambda} c_\lambda T_\lambda \phi = 0$. By taking the Fourier transform, we obtain the relation
\begin{equation}\label{G_zero}
    \underbrace{\sum_{\lambda \in \Lambda} c_\lambda e^{-2 \pi i \lambda \cdot t}}_{\coloneqq G(t)}  {\mathcal{F}} \phi(t) = 0
\end{equation}
which holds for almost every $t \in {{\mathbb R}^d}$. By assumption we have that
\begin{equation}\label{eq:lower_triangle_bound}
    \mathfrak{p}_{\Lambda^*}[\phi](t) = \sum_{\lambda^* \in \Lambda^*} |{\mathcal{F}} \phi (t+\lambda^*)|^2 \geq A >0
\end{equation}
for almost every $t \in \mathcal{P}(\Lambda^*)$. Since $\mathfrak{p}_{\Lambda^*}[\phi]$ is $\Lambda^*$-periodic, it follows that the lower bound given in equation \eqref{eq:lower_triangle_bound} holds for almost every $t \in {{\mathbb R}^d}$. Moreover, it shows that there exists no measurable $\Lambda^*$-periodic set $\Omega \subseteq {{\mathbb R}^d}$ of positive Lebesgue measure such that ${\mathcal{F}} \phi$ vanishes almost everywhere on $\Omega$. Since the map $G$ is $\Lambda^*$-periodic as well, equation \eqref{G_zero} implies that $G$ must vanish almost everywhere. The uniqueness theorem for Fourier coefficients finally shows that $c_\lambda = 0$ for every $\lambda \in \Lambda$, as desired.

\label{thm:phaseRetrieval_discB}
Let $g \in {L^2({\mathbb R}^d)}$ be an arbitrary window function, and let $\mathcal{L} \subseteq {{\mathbb R}^{2d}}$. Then $(g,\mathcal{L})$ is never a uniqueness pair, provided that $\mathcal{L}$ satisfies one of the following two conditions:
\begin{enumerate}
    \item $\mathcal{L}=S({{\mathbb R}^d} \times \Lambda)$ where $S \in \mathrm{Sp}_{2d}({\mathbb R})$ is a symplectic matrix and $\Lambda \subseteq {{\mathbb R}^d}$ is a lattice.
    \item $\mathcal{L}=L{\mathbb Z}^{2d}$ is a lattice with generating matrix $L \in \mathrm{GL}_{2d}({\mathbb R})$ which factors into $L=ST$ where $S \in \mathrm{Sp}_{2d}({\mathbb R})$ is symplectic and $T$ is a block-diagonal matrix of the form
    $$
T = \begin{pmatrix} A & 0 \\ 0 & B \end{pmatrix}, \ \ A,B \in \mathrm{GL}_d({\mathbb R}).
$$
\end{enumerate}

\label{cor_rem}
Let $g \in {L^2({\mathbb R}^d)}$ be an arbitrary window function, and let $\mathcal{L} \subseteq {{\mathbb R}^{2d}}$. Then $(g,\mathcal{L})$ is never a uniqueness pair, provided that $\mathcal{L}$ is a lattice of the following form:
\begin{enumerate}
    \item $\mathcal{L} = \alpha S{\mathbb Z}^{2d}$ with $S \in \mathrm{Sp}_{2d}({\mathbb R})$ a symplectic matrix and $\alpha>0$ an arbitrary density parameter.
    \item $\mathcal{L}$ is rectangular, i.e. it is generated by an invertible diagonal matrix.
    \item $\mathcal{L}$ is separable.
    \item $\mathcal{L}=\alpha {\mathbb Z}^d \times \beta {\mathbb Z}^d$ with arbitrary density parameters $\alpha,\beta \in {\mathbb R} \setminus \{ 0 \}$.
\end{enumerate}

Let $g \in {L^2({\mathbb R}^d)}$ be a window function, and suppose that $\mathcal{L} = L{\mathbb Z}^{2d}$ is a lattice as given in Theorem \ref{thm:phaseRetrieval_discB}, i.e., $L=ST$ with $S$ symplectic and $T$ block-diagonal. According to Theorem \ref{thm:phaseRetrieval_discB} there exist $f_1,f_2 \in {L^2({\mathbb R}^d)}$ such that
\begin{equation}\label{eqqq}
    |V_g(f_1)(z)| = |V_g(f_2)(z)| \ \ \forall z \in \mathcal{L}
\end{equation}
and $f_2 \nsim f_2$. For every $p=(a,b), z=(x,\omega) \in {{\mathbb R}^d} \times {{\mathbb R}^d}$ and every $u \in {L^2({\mathbb R}^d)}$, the covariance property of the STFT (Lemma \ref{lma:stft_properties}(2)) shows that
\begin{equation}\label{covvv}
    V_gu(p+z) = V_gu(a+x,b+\omega) = e^{-2 \pi i a \cdot \omega} V_g(T_{-a}M_{-b}u)(z).
\end{equation}
Accordingly, if $f_1,f_2$ are given as above and $h_1,h_2$ are defined by
\begin{equation*}
    \begin{split}
        h_1 & \coloneqq M_b T_a f_1 \\
        h_2 & \coloneqq M_b T_a f_2
    \end{split}
\end{equation*}
then the equations \eqref{eqqq} and \eqref{covvv} imply that
$$
|V_g(h_1)(y)| = |V_g(h_2)(y)| \ \ \forall y \in p + \mathcal{L}.
$$
Further, the property of two functions being equal up to a global phase is invariant under time-frequency shifts. Hence, $f_1 \nsim f_2$ if and only if $h_1 \nsim h_2$. This shows that the conclusions of Theorem \ref{thm:phaseRetrieval_discB} hold true if the lattice $\mathcal{L}$ is replaced by a shifted lattice $p+\mathcal{L}$ with $p \in {\mathbb R}^{2d}$ an arbitrary vector.

Let $\Lambda$ be the scaled standard rectangular lattice $\Lambda=8{\mathbb Z}^2$ and define $\lambda_1,\lambda_2,\lambda_3 \in \Lambda$ and $c_{\lambda_1},c_{\lambda_2},c_{\lambda_3} \in {\mathbb C}$ via
\begin{align*}
    \lambda_1 &=(0,0), & \lambda_2&=(1,0), & \lambda_3&=(0,1), \\
    c_{\lambda_1} &= 1, & c_{\lambda_2} &= i, & c_{\lambda_3} &= 1+i.
\end{align*}
The set of points $\{ 1,i,1+i \}$ does not lie on a line in the complex plane passing through the origin, which implies that $\{ c_\lambda \} \in c_{00}(\Lambda) \cap \ell_\mathcal{O}^2(\Lambda)$. Consequently, if
$$
f_1 = c_1 T_{\lambda_1} \mathcal{R}g+c_2 T_{\lambda_2} \mathcal{R}g+c_3 T_{\lambda_3} \mathcal{R}g
$$
then according to Theorem \ref{thm:equalSpectrograms}, and Theorem \ref{thm:nonEquivalence}, $Q_xf_1$ vanishes on $\Lambda^* = \tfrac{1}{8}{\mathbb Z}^2$ and $f_1 \nsim (f_1)_\times$. Contour plots of $Q_xf_1$ for different choices of $x$ are provided in Figure \ref{fig:rectangular}.

